<?php
namespace Modules\Glitter\Workflow\Services;
use Modules\Glitter\Workflow\Models\{WorkflowAcceptance,WorkflowExecution,WorkflowActionExecution};use Modules\Glitter\Workflow\Enums\{AcceptanceStatus,WorkflowExecutionStatus,ActionExecutionStatus};use Modules\Glitter\Workflow\Jobs\{ProcessWorkflowAcceptanceJob,ProcessWorkflowExecutionJob,ProcessWorkflowDelayResumeJob};use Modules\Glitter\Workflow\Services\Runtime\ActionRunningRecoveryPolicy;
final class WorkflowRecoveryService { public const DEFAULT_LIMIT=50; public const MAX_LIMIT=200; public function recover(int $limit=self::DEFAULT_LIMIT,bool $dryRun=false):array{$limit=min(max($limit,1),self::MAX_LIMIT);$out=['acceptances'=>[],'executions'=>[],'delays'=>[]];$as=WorkflowAcceptance::query()->where('status',AcceptanceStatus::Pending)->orderBy('created_at')->orderBy('id')->limit($limit)->get();foreach($as as $a){$out['acceptances'][]=$a->uuid;if(!$dryRun)ProcessWorkflowAcceptanceJob::dispatch($a->uuid)->afterCommit();}$es=WorkflowExecution::query()->whereIn('status',[WorkflowExecutionStatus::Pending,WorkflowExecutionStatus::Running])->orderBy('created_at')->orderBy('id')->limit($limit)->get();foreach($es as $e){$next=$e->actionExecutions()->orderBy('action_index')->get()->first(fn($a)=>$a->status!==ActionExecutionStatus::Succeeded);if(!$next||($next->action_type->isExecutable()&&$next->status===ActionExecutionStatus::Running&&ActionRunningRecoveryPolicy::decision($next->action_type,$next->started_at,$next->attempt_count,now())===ActionRunningRecoveryPolicy::HOLD)||($next->action_type->isExecutable()&&$next->status===ActionExecutionStatus::Scheduled&&(!$next->scheduled_at||$next->scheduled_at->isFuture())))continue;$out['executions'][]=$e->uuid;if(!$dryRun)ProcessWorkflowExecutionJob::dispatch($e->uuid)->afterCommit();}$ds=WorkflowActionExecution::query()->where('status',ActionExecutionStatus::Scheduled)->whereNotNull('scheduled_at')->where('scheduled_at','<=',now())->orderBy('scheduled_at')->orderBy('id')->limit($limit)->get();foreach($ds as $d){if($d->action_type->value==='webhook')continue;$out['delays'][]=$d->uuid;if(!$dryRun)ProcessWorkflowDelayResumeJob::dispatch($d->uuid)->afterCommit();}return $out;}}
